* HELP transactions -- producer demo (writes one item per ENTER to a TS queue).
MAP HELP1 SIZE 24x80
  FIELD AT 0,15 LEN 32 PROT BRIGHT COLOR=BLUE   "Welcome to BRICKS Transaction Server"
  FIELD AT 0,60 LEN 5  PROT COLOR=TURQUOISE          "TERM="
  INPUT TERMID  AT 0,65 LEN 8  PROT COLOR=TURQUOISE
  FIELD AT 2,0  LEN 25  PROT COLOR=BLUE   "TRANSACTION       "
  FIELD AT 3,0  LEN 25  PROT COLOR=GREEN   "CSSN LOGON             -  LOGON"
  FIELD AT 4,0  LEN 25  PROT COLOR=GREEN   "CSSF LOGOFF            -  LOGOFF"
  FIELD AT 5,0  LEN 45  PROT COLOR=GREEN   "CSSF GOODNIGHT / DISC  -  DISCONNECT FROM BRICKS"
  FIELD AT 6,0  LEN 45  PROT COLOR=GREEN   "CEMT INQUIRE           -  INQUIRE BRICKS RESOURCES"
  FIELD AT 7,0  LEN 45  PROT COLOR=GREEN   "CEMT MONITOR           -  BRICKS INTERNALS MONITOR"
  FIELD AT 8,0  LEN 45  PROT COLOR=RED   "IDCA                   -  IDCAMS VSAM ADMINISTRATION (ADMIN ONLY)"
  FIELD AT 9,0  LEN 30  PROT COLOR=RED     "CEMT PERFORM           -  MASTER CONSOLE (ADMIN ONLY)"
  FIELD AT 10,0  LEN 30  PROT COLOR=RED     "CEDA                   -  RESOURCES DEFINITIONS(ADMIN ONLY)"
  FIELD AT 11,0  LEN 30  PROT COLOR=TURQUOISE  "ISPF                   -  PROGRAM DEVELOPMENT (DEV GROUP ONLY)"
  FIELD AT 12,0  LEN 30  PROT COLOR=TURQUOISE  "CECI                   -  Interactive EXEC CICS/SQL/WEB TESTING (DEV)"
  FIELD AT 14,0  LEN 30  PROT COLOR=YELLOW "BANK                   -  PSEUDO-CONVERSATIONAL BANKING APP"
  FIELD AT 15,0  LEN 30  PROT COLOR=YELLOW "CUST                   -  PSEUDO-CONVERSATIONAL CRM"
  FIELD AT 16,0  LEN 30  PROT COLOR=PINK   "CHAT                   -  PSEUDO-CONVERSATIONAL REAL-TIME CHAT"
  FIELD AT 17,0  LEN 30  PROT COLOR=PINK   "MNDL                   -  Mandelbrot !!"
  FIELD AT 19,2 LEN 45  PROT COLOR=WHITE   "To logon with CSSN, the operator must grant you an account"
  FIELD AT 20,2 LEN 45  PROT COLOR=WHITE   "To use ISPF, you must have a DEV group assignment"
  FIELD AT 22,0 LEN 50 PROT COLOR=BLUE     "PF3=Exit"
  CURSOR        AT 22,0
ENDMAP
